import 'package:flutter/material.dart';
import '../../data/app_database.dart';
import '../../models/app_models.dart';
import '../common/ui.dart';
class HomeScreen extends StatefulWidget{const HomeScreen({super.key});@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{List<Trip> trips=[];List<Vehicle> vehicles=[];List<FuelEntry> fuel=[];Future<void> load()async{final db=AppDatabase.instance;final a=await db.trips();final b=await db.vehicles();final c=await db.fuelEntries();if(mounted)setState((){trips=a;vehicles=b;fuel=c;});}@override void initState(){super.initState();load();}
 @override Widget build(BuildContext context){final distance=trips.fold<double>(0,(s,t)=>s+t.distanceKm);final expenses=fuel.fold<double>(0,(s,e)=>s+e.amount);double measuredKm=0,measuredL=0;for(final v in vehicles){final list=fuel.where((e)=>e.vehicleId==v.id).toList()..sort((a,b)=>a.date.compareTo(b.date));FuelEntry? previous;double litres=0;for(final e in list){litres+=e.litres;if(e.fullTank){if(previous!=null){final km=e.odometer-previous.odometer;if(km>0){measuredKm+=km;measuredL+=litres;}}previous=e;litres=0;}}}final mileage=measuredL>0?measuredKm/measuredL:null;
 return RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.fromLTRB(20,18,20,24),children:[const PageTitle('Bike Mileage Pro'),_metric('Overall actual mileage',mileage==null?'—':'${mileage.toStringAsFixed(2)} km/L'),_metric('Total trip distance','${distance.toStringAsFixed(1)} km'),_metric('Fuel expenses','₹${expenses.toStringAsFixed(2)}'),_metric('Vehicles','${vehicles.length}'),const SizedBox(height:8),const Text('Actual mileage is calculated from consecutive full-tank odometer entries. Trip distance is calculated from saved GPS trips. Add at least two full-tank records to see measured mileage.',style:TextStyle(color:Colors.white60))]));}
 Widget _metric(String label,String value)=>Padding(padding:const EdgeInsets.only(bottom:16),child:Panel(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label,style:const TextStyle(color:Colors.white60,fontSize:16)),const SizedBox(height:14),Text(value,style:const TextStyle(fontSize:28,fontWeight:FontWeight.bold))])));
}
